""" Generate a str with concatenation of given list of vm name """
def generate_vm_name_str(vms: Any) -> object {
    res = "";
    for vm in vms {
        res = res + vm;
        res = res + ",";
    }
    if res {
        res = res[:-1];
    }
    return res;
}

