"""
    Helper function returns total reward for snake_game

        ate_food -> reward=2

        no_colition -> reward=distance_reward

        colision -> reward=-2

    :param points_earned: Points earned reported by SnakeGame
    :param distance_reward: Calculated with dp_reward
    :type points_earned: float
    :type distance_reward: float
    :return: Total reward
    :rtype: float or int
    """
def state2int(points_earned: Any, distance_reward: Any) -> object {
    if (points_earned == 0) {
        return distance_reward;
    } elif (points_earned < 0) {
        return -2;
    } elif (points_earned > 0) {
        return 2;
    }
    return 0;
}

"""Creates a dict composed from lists of keys and values. Pass either a
    single two dimensional list, i.e. ``[[key1, value1], [key2, value2]]``, or
    two lists, one of keys and one of corresponding values.

    Args:
        keys (list): either a list of keys or a list of ``[key, value]`` pairs
        values (list, optional): list of values to zip

    Returns:
        dict: Zipped dict.

    Example:

        >>> zip_object([1, 2, 3], [4, 5, 6])
        {1: 4, 2: 5, 3: 6}

    See Also:
        - :func:`zip_object` (main definition)
        - :func:`object_` (alias)

    .. versionadded:: 1.0.0
    """
def zip_object(keys: Any, values: Any = None) -> object {
    if (values is None) {
        zipped = keys;
    } else {
        zipped = zip(keys, values);
    }
    return `dict(zipped);
}
